import sys, os, re

class PhpArray:
    def __init__(self, items=None):
        self.data = {}
        self.order = []
        self.auto_idx = 0
        if items:
            for k, v in items:
                self.set(k, v)

    def set(self, key, val):
        if key is None:
            key = self.auto_idx
        if isinstance(key, int):
            if key >= self.auto_idx:
                self.auto_idx = key + 1
        if key not in self.data:
            self.order.append(key)
        self.data[key] = val

    def get(self, key, default=None):
        return self.data.get(key, default)

    def __getitem__(self, key):
        return self.data.get(key, None)

    def __setitem__(self, key, val):
        self.set(key, val)

    def __len__(self):
        return len(self.order)

    def __iter__(self):
        for k in self.order:
            yield k, self.data[k]

    def __repr__(self):
        return f"PhpArray({self.data})"

print("PhpArray initialized successfully!")
