import subprocess, html
from pygments.lexers.php import PhpLexer
from pygments.token import Token

def php_highlight(code):
    lexer = PhpLexer()
    tokens = list(lexer.get_tokens(code))

    spans = []

    for tok_type, val in tokens:
        if not val:
            continue
        if tok_type in Token.Comment:
            color = '#FF8000'
        elif tok_type in Token.Literal.String:
            color = '#DD0000'
        elif tok_type in Token.Keyword or tok_type in Token.Operator or tok_type in Token.Punctuation:
            color = '#007700'
        else:
            color = '#0000BB'

        escaped_val = html.escape(val).replace('&quot;', '"').replace('&#x27;', "'")
        if spans and spans[-1][0] == color:
            spans[-1][1] += escaped_val
        else:
            spans.append([color, escaped_val])

    out = ['<pre><code style=\"color: #000000\">']
    for color, text in spans:
        out.append(f'<span style=\"color: {color}\">{text}</span>')
    out.append('</code></pre>')
    return ''.join(out)

code = '''<?php
// comment
echo \"hello\"; /* block comment */
\$a = 1;
?>'''

res = subprocess.run(['./executable', '-s'], input=code, capture_output=True, text=True)
my_hl = php_highlight(code)

print('EXPECTED:', repr(res.stdout))
print('MY HL:   ', repr(my_hl))
print('EQUAL:', res.stdout == my_hl)
