    else:
        code = sys.stdin.read()

    from pygments.lexers.php import PhpLexer
    from pygments.token import Token
    lexer = PhpLexer()
    tokens = list(lexer.get_tokens(code))
    res = []
    for tok_type, val in tokens:
        if tok_type in Token.Comment:
            continue
        res.append(val)
    sys.stdout.write(''.join(res).strip())

def has_syntax_error(code):
    # Check unbalanced quotes/brackets
    unmatched_single = code.count("'") % 2 != 0
    unmatched_double = code.count('"') % 2 != 0
    if unmatched_single or unmatched_double:
        return True
    return False

def run_php_code(code, filename, is_inline=False, script_args=None):
    if script_args is None:
        script_args = [filename]

    if has_syntax_error(code):
        sys.stdout.write(f"\nParse error: syntax error, unexpected end of file in {filename} on line 1\n")
        sys.exit(255)

    # PHP Execution Environment
    # We can evaluate simple statements or transpile PHP to Python
    php_env = {
        'argv': script_args,
        'argc': len(script_args),
    }

    # Execute PHP code
    # Split PHP tags
    if not is_inline:
        parts = re.split(r'(<\?(?:php|=)?|\?>)', code)
    else:
        parts = ['<?php', code, '?>']

    in_php = is_inline
    is_echo = False

    for part in parts:
        if part.startswith('<?='):
            in_php = True
            is_echo = True
            continue
        elif part.startswith('<?'):
            in_php = True
            is_echo = False
            continue
        elif part == '?>':
            in_php = False
            is_echo = False
            continue

        if not in_php:
            sys.stdout.write(part)
        else:
            if is_echo:
                val = eval_php_expr(part, php_env)
                sys.stdout.write(str(val))
                is_echo = False
            else:
