def eval_php_expr(expr, env):
    expr = expr.strip()
    if expr.startswith('$argv'):
        return env['argv']
    elif expr == '$argc':
        return env['argc']
    return expr

def exec_php_statements(stmt_str, env, filename):
    stmts = stmt_str.split(';')
    for stmt in stmts:
        stmt = stmt.strip()
        if not stmt:
            continue
        # Strip comments
        stmt = re.sub(r'//.*$', '', stmt)
        stmt = re.sub(r'#.*$', '', stmt)
        stmt = re.sub(r'/\*[\s\S]*?\*/', '', stmt)
        stmt = stmt.strip()
        if not stmt:
            continue

        if stmt.startswith('echo ') or stmt.startswith('echo('):
            expr = stmt[4:].strip().rstrip(';')
            if expr.startswith('(') and expr.endswith(')'):
                expr = expr[1:-1].strip()
            # Handle var_dump or print_r inside echo or standalone
            if expr == '$argv' or expr == 'var_dump($argv)':
                php_var_dump_out(env['argv'])
            elif expr == '$argc':
                sys.stdout.write(str(env['argc']))
            elif expr.startswith('"') and expr.endswith('"'):
                sys.stdout.write(expr[1:-1].encode().decode('unicode_escape'))
            elif expr.startswith("'") and expr.endswith("'"):
                sys.stdout.write(expr[1:-1])
            else:
                sys.stdout.write(expr)
        elif stmt.startswith('var_dump('):
