    unmatched_double = code.count('"') % 2 != 0
    if unmatched_single or unmatched_double:
        return True
    return False

def run_php_code(code, filename, is_inline=False, script_args=None):
    if script_args is None:
        script_args = [filename]

    if has_syntax_error(code):
        sys.stdout.write(f"\nParse error: syntax error, unexpected end of file in {filename} on line 1\n")
        sys.exit(255)

    php_env = {
        'argv': script_args,
        'argc': len(script_args),
    }

    if not is_inline:
        parts = re.split(r'(<\?(?:php|=)?|\?>)', code)
    else:
        parts = ['<?php', code, '?>']

    in_php = is_inline
    is_echo = False

    for part in parts:
        if part.startswith('<?='):
            in_php = True
            is_echo = True
            continue
        elif part.startswith('<?'):
            in_php = True
            is_echo = False
            continue
        elif part == '?>':
            in_php = False
            is_echo = False
            continue

        if not in_php:
            sys.stdout.write(part)
