    ind = '  ' * indent
    if isinstance(val, list):
        sys.stdout.write(f'{ind}array({len(val)}) {{\n')
        for idx, item in enumerate(val):
            sys.stdout.write(f'{ind}  [{idx}]=>\n')
            if isinstance(item, str):
                sys.stdout.write(f'{ind}  string({len(item)}) "{item}"\n')
            elif isinstance(item, int):
                sys.stdout.write(f'{ind}  int({item})\n')
            else:
                sys.stdout.write(f'{ind}  {item}\n')
        sys.stdout.write(f'{ind}}}\n')
    elif isinstance(val, int):
        sys.stdout.write(f'{ind}int({val})\n')
    elif isinstance(val, str):
        sys.stdout.write(f'{ind}string({len(val)}) "{val}"\n')
