        elif arg == '-w':
            filepath = args[i+1] if i + 1 < len(args) else None
            do_strip(filepath)
            sys.exit(0)
        elif arg.startswith('-'):
            opt = arg[1] if len(arg) > 1 else ''
            sys.stderr.write(f"Error in argument {i+1}, char 2: option not found {opt}\n")
            sys.stdout.write(usage_text(progname))
