def execute_repeat(count, code, filename, is_inline, script_args):
    for c in range(count):
        if count > 1:
            if c == 0:
                sys.stdout.write("Executing for the first time...\n")
            else:
                sys.stdout.write("Finished execution, repeating...\n")
        run_php_code(code, filename, is_inline=is_inline, script_args=script_args)

def run_line_processing(begin_code, line_code, line_file, end_code, script_args):
    env = {
        'argv': PhpArray(script_args),
        'argc': len(script_args),
