    lexer = PhpLexer()
    tokens = list(lexer.get_tokens(code))
    res = []
    for tok_type, val in tokens:
        if tok_type in Token.Comment:
            continue
        res.append(val)
    sys.stdout.write(''.join(res).strip())

def has_syntax_error(code):
    unmatched_single = code.count("'") % 2 != 0
    unmatched_double = code.count('"') % 2 != 0
    if unmatched_single or unmatched_double:
        return True
    return False

def run_php_code(code, filename, is_inline=False, script_args=None, env=None):
    if script_args is None:
        script_args = [filename]

    if has_syntax_error(code):
        sys.stdout.write(f"\nParse error: syntax error, unexpected end of file in {filename} on line 1\n")
        sys.exit(255)

    if env is None:
        env = {
            'argv': PhpArray(script_args),
            'argc': len(script_args),
        }

    if not is_inline:
        parts = re.split(r'(<\?(?:php|=)?|\?>)', code)
    else:
        parts = ['<?php', code, '?>']

    in_php = is_inline
    is_echo = False

    for part in parts:
        if part.startswith('<?='):
            in_php = True
            is_echo = True
            continue
        elif part.startswith('<?'):
            in_php = True
            is_echo = False
            continue
        elif part == '?>':
            in_php = False
            is_echo = False
            continue

        if not in_php:
            sys.stdout.write(part)
        else:
            if is_echo:
                val = eval_php_expr(part, env, filename)
                sys.stdout.write(str(val))
                is_echo = False
            else:
                exec_php_statements(part, env, filename)

def eval_php_expr(expr, env, filename="Command line code"):
    expr = expr.strip()
    if not expr:
        return ""
    if expr == '$argv':
        return env.get('argv')
    elif expr == '$argc':
        return env.get('argc')
    elif expr == '$argn':
        return env.get('argn', '')
    elif expr == '$argi':
        return env.get('argi', 0)
    elif expr.startswith('$'):
        var_name = expr[1:]
        if var_name in env:
            return env[var_name]
        sys.stdout.write(f"\nWarning: Undefined variable ${var_name} in {filename} on line 1\n")
        return None
    elif expr.startswith('"') and expr.endswith('"'):
        val = expr[1:-1].encode().decode('unicode_escape')
        # Interpolate variables $var or {$var}
        def repl(m):
            vname = m.group(1) or m.group(2)
            return str(env.get(vname, ''))
        val = re.sub(r'\{\$([a-zA-Z_]\w*)\}|\$([a-zA-Z_]\w*)', repl, val)
        return val
    elif expr.startswith("'") and expr.endswith("'"):
        return expr[1:-1]
    try:
        return int(expr)
    except ValueError:
        try:
            return float(expr)
        except ValueError:
            return expr

def exec_php_statements(stmt_str, env, filename):
    stmts = stmt_str.split(';')
    for stmt in stmts:
        stmt = stmt.strip()
        if not stmt:
            continue
        stmt = re.sub(r'//.*$', '', stmt)
        stmt = re.sub(r'#.*$', '', stmt)
        stmt = re.sub(r'/\*[\s\S]*?\*/', '', stmt)
        stmt = stmt.strip()
        if not stmt:
            continue

        if stmt.startswith('echo ') or stmt.startswith('echo('):
            expr = stmt[4:].strip().rstrip(';')
            if expr.startswith('(') and expr.endswith(')'):
                expr = expr[1:-1].strip()
            # Handle concatenation with .
            parts = expr.split('.')
            for p in parts:
                p = p.strip()
                if p == '$argv' or p == 'var_dump($argv)':
                    sys.stdout.write(php_var_dump(env.get('argv')))
                elif p == '$argc':
