def eval_php_expr(expr, env, filename="Command line code"):
    expr = expr.strip()
    if not expr:
        return ""
    if expr == '$argv':
        return env.get('argv')
    elif expr == '$argc':
        return env.get('argc')
    elif expr == '$argn':
        return env.get('argn', '')
    elif expr == '$argi':
        return env.get('argi', 0)
    elif expr.startswith('$'):
        var_name = expr[1:]
        if var_name in env:
            return env[var_name]
