class PhpArray:
    def __init__(self, items=None):
        self.data = {}
        self.order = []
        self.next_idx = 0
        if items is not None:
            if isinstance(items, dict):
                for k, v in items.items():
                    self.set(k, v)
            elif isinstance(items, (list, tuple)):
                for item in items:
                    if isinstance(item, tuple) and len(item) == 2:
                        self.set(item[0], item[1])
                    else:
                        self.append(item)

    def set(self, key, val):
        if key is None:
            key = self.next_idx
        elif isinstance(key, float):
            key = int(key)
        if isinstance(key, int):
            if key >= self.next_idx:
                self.next_idx = key + 1
        if key not in self.data:
            self.order.append(key)
        self.data[key] = val

    def append(self, val):
        self.set(self.next_idx, val)

    def get(self, key, default=None):
        return self.data.get(key, default)

    def __getitem__(self, key):
        return self.data.get(key, None)

    def __setitem__(self, key, val):
        self.set(key, val)

    def __contains__(self, key):
        return key in self.data

    def __len__(self):
        return len(self.order)

    def items(self):
        for k in self.order:
            yield k, self.data[k]

    def keys(self):
        return list(self.order)

    def values(self):
        return [self.data[k] for k in self.order]

def php_var_dump(val, indent=0):
    ind = '  ' * indent
    if val is None:
        return f'{ind}NULL\n'
    elif val is True:
        return f'{ind}bool(true)\n'
    elif val is False:
        return f'{ind}bool(false)\n'
    elif isinstance(val, int):
        return f'{ind}int({val})\n'
    elif isinstance(val, float):
        return f'{ind}float({val})\n'
    elif isinstance(val, str):
        return f'{ind}string({len(val)}) "{val}"\n'
    elif isinstance(val, PhpArray):
        res = f'{ind}array({len(val)}) {{\n'
        for k, v in val.items():
            if isinstance(k, int):
                res += f'{ind}  [{k}]=>\n'
            else:
                res += f'{ind}  ["{k}"]=>\n'
            res += php_var_dump(v, indent + 1)
