    ind = '    ' * indent
    if val is None:
        out = ''
    elif val is True:
        out = '1'
    elif val is False:
        out = ''
    elif isinstance(val, (int, float, str)):
        out = str(val)
    elif isinstance(val, (PhpArray, list, dict)):
        arr = val if isinstance(val, PhpArray) else PhpArray(val)
        out = 'Array\n' + ind + '(\n'
        for k, v in arr.items():
            out += ind + f'    [{k}] => '
            if isinstance(v, (PhpArray, list, dict)):
                out += php_print_r(v, True, indent + 1) + '\n'
            else:
                out += str(v) + '\n'
        out += ind + ')'
    else:
        out = str(val)

    if return_str:
        return out
    else:
        sys.stdout.write(out)
