                    sys.stdout.write("Zend Extension [ Zend OPcache 8.6.0-dev Copyright (c) by Zend Technologies <http://www.zend.com/> ]\n\n")
                    sys.exit(0)
                else:
                    sys.stdout.write(f'Exception: Zend Extension "{name}" does not exist\n')
                    sys.exit(1)
            else:
                sys.stderr.write(f"Error in argument {i+1}, char 1: no argument for option -\n")
                sys.stdout.write(usage_text(progname))
                sys.exit(1)
        elif arg == '--ri':
            if i + 1 < len(args):
                name = args[i+1]
                if name in RI_DATA:
                    sys.stdout.write(RI_DATA[name])
                    sys.exit(0)
                else:
                    sys.stdout.write(f"Extension '{name}' not present.\n")
                    sys.exit(1)
            else:
                sys.stderr.write(f"Error in argument {i+1}, char 1: no argument for option -\n")
                sys.stdout.write(usage_text(progname))
                sys.exit(1)
        elif arg == '-r':
            if i + 1 < len(args):
                code = args[i+1]
                script_args = ['Standard input code'] + args[i+2:]
                execute_repeat(repeat_count, code, "Command line code", is_inline=True, script_args=script_args)
                sys.exit(0)
            else:
                sys.stderr.write(f"Error in argument {i+1}, char 2: no argument for option r\n")
                sys.stdout.write(usage_text(progname))
                sys.exit(1)
        elif arg == '-f':
            if i + 1 < len(args):
                filepath = args[i+1]
                if not os.path.exists(filepath):
                    sys.stderr.write(f"Could not open input file: {filepath}\n")
                    sys.exit(1)
                with open(filepath) as f:
                    code = f.read()
                script_args = [filepath] + args[i+2:]
                execute_repeat(repeat_count, code, filepath, is_inline=False, script_args=script_args)
                sys.exit(0)
            else:
                sys.stderr.write(f"Error in argument {i+1}, char 2: no argument for option f\n")
                sys.stdout.write(usage_text(progname))
                sys.exit(1)
        elif arg == '-B':
            if i + 1 < len(args):
                begin_code = args[i+1]
                i += 2
                continue
            else:
                sys.stderr.write(f"Error in argument {i+1}, char 2: no argument for option B\n")
                sys.stdout.write(usage_text(progname))
                sys.exit(1)
        elif arg == '-R':
            if i + 1 < len(args):
                line_code = args[i+1]
                i += 2
                script_args = ['Standard input code'] + args[i:]
                run_line_processing(begin_code, line_code, None, end_code, script_args)
                sys.exit(0)
            else:
                sys.stderr.write(f"Error in argument {i+1}, char 2: no argument for option R\n")
                sys.stdout.write(usage_text(progname))
                sys.exit(1)
        elif arg == '-E':
            if i + 1 < len(args):
                end_code = args[i+1]
                i += 2
                continue
            else:
                sys.stderr.write(f"Error in argument {i+1}, char 2: no argument for option E\n")
                sys.stdout.write(usage_text(progname))
                sys.exit(1)
        elif arg in ('-c', '-d', '-S', '-t'):
            if i + 1 >= len(args):
                opt = arg[1]
                sys.stderr.write(f"Error in argument {i+1}, char 2: no argument for option {opt}\n")
                sys.stdout.write(usage_text(progname))
                sys.exit(1)
            i += 2
            continue
        elif arg == '-l':
            filepath = args[i+1] if i + 1 < len(args) else None
            do_lint(filepath)
            sys.exit(0)
        elif arg == '-s':
            filepath = args[i+1] if i + 1 < len(args) else None
            do_highlight(filepath)
            sys.exit(0)
        elif arg == '-w':
            filepath = args[i+1] if i + 1 < len(args) else None
            do_strip(filepath)
            sys.exit(0)
        elif arg.startswith('-'):
            opt = arg[1] if len(arg) > 1 else ''
            sys.stderr.write(f"Error in argument {i+1}, char 2: option not found {opt}\n")
            sys.stdout.write(usage_text(progname))
            sys.exit(1)
        else:
            filepath = arg
            if not os.path.exists(filepath):
                sys.stderr.write(f"Could not open input file: {filepath}\n")
                sys.exit(1)
            with open(filepath) as f:
                code = f.read()
            script_args = [filepath] + args[i+1:]
            execute_repeat(repeat_count, code, filepath, is_inline=False, script_args=script_args)
            sys.exit(0)

        i += 1

def execute_repeat(count, code, filename, is_inline, script_args):
    for c in range(count):
        if count > 1:
            if c == 0:
                sys.stdout.write("Executing for the first time...\n")
            else:
                sys.stdout.write("Finished execution, repeating...\n")
        run_php_code(code, filename, is_inline=is_inline, script_args=script_args)

def run_line_processing(begin_code, line_code, line_file, end_code, script_args):
    env = {
        'argv': PhpArray(script_args),
        'argc': len(script_args),
    }
    if begin_code:
        run_php_code(begin_code, "Command line run code", is_inline=True, script_args=script_args, env=env)

    lines = sys.stdin.read().splitlines()
    for idx, line in enumerate(lines, start=1):
        env['argn'] = line
        env['argi'] = idx
        if line_code:
            run_php_code(line_code, "Command line run code", is_inline=True, script_args=script_args, env=env)

    if end_code:
        run_php_code(end_code, "Command line run code", is_inline=True, script_args=script_args, env=env)

def do_lint(filepath):
    if filepath:
        if not os.path.exists(filepath):
            sys.stderr.write(f"Could not open input file: {filepath}\n")
            sys.exit(1)
        with open(filepath) as f:
            code = f.read()
        fname = filepath
    else:
        code = sys.stdin.read()
        fname = "Standard input code"

    if has_syntax_error(code):
        sys.stdout.write(f"\nParse error: syntax error, unexpected end of file in {fname} on line 1\nErrors parsing {fname}\n")
        sys.exit(255)
    else:
        sys.stdout.write(f"No syntax errors detected in {fname}\n")
        sys.exit(0)

def do_highlight(filepath):
    if filepath:
        if not os.path.exists(filepath):
            sys.stderr.write(f"Could not open input file: {filepath}\n")
            sys.exit(1)
        with open(filepath) as f:
            code = f.read()
    else:
        code = sys.stdin.read()

    from pygments.lexers.php import PhpLexer
    from pygments.token import Token
    lexer = PhpLexer()
    tokens = list(lexer.get_tokens(code))
    spans = []
    for tok_type, val in tokens:
        if not val:
            continue
        if tok_type in Token.Comment:
            color = '#FF8000'
        elif tok_type in Token.Literal.String:
            color = '#DD0000'
        elif tok_type in Token.Keyword or tok_type in Token.Operator or tok_type in Token.Punctuation:
            color = '#007700'
        else:
            color = '#0000BB'

        escaped_val = html.escape(val, quote=False)
        if spans and spans[-1][0] == color:
            spans[-1][1] += escaped_val
        else:
            spans.append([color, escaped_val])

    out = ['<pre><code style="color: #000000">']
    for color, text in spans:
        out.append(f'<span style="color: {color}">{text}</span>')
    out.append('</code></pre>')
    sys.stdout.write(''.join(out))

def do_strip(filepath):
    if filepath:
        if not os.path.exists(filepath):
            sys.stderr.write(f"Could not open input file: {filepath}\n")
            sys.exit(1)
        with open(filepath) as f:
            code = f.read()
    else:
        code = sys.stdin.read()

    from pygments.lexers.php import PhpLexer
    from pygments.token import Token
    lexer = PhpLexer()
    tokens = list(lexer.get_tokens(code))
    res = []
    for tok_type, val in tokens:
        if tok_type in Token.Comment:
            continue
        res.append(val)
    sys.stdout.write(''.join(res).strip())

def has_syntax_error(code):
    unmatched_single = code.count("'") % 2 != 0
    unmatched_double = code.count('"') % 2 != 0
    if unmatched_single or unmatched_double:
        return True
    return False

def run_php_code(code, filename, is_inline=False, script_args=None, env=None):
    if script_args is None:
        script_args = [filename]

    if has_syntax_error(code):
        sys.stdout.write(f"\nParse error: syntax error, unexpected end of file in {filename} on line 1\n")
        sys.exit(255)

    if env is None:
        env = {
            'argv': PhpArray(script_args),
            'argc': len(script_args),
        }

    if not is_inline:
        parts = re.split(r'(<\?(?:php|=)?|\?>)', code)
    else:
        parts = ['<?php', code, '?>']

    in_php = is_inline
    is_echo = False

    for part in parts:
        if part.startswith('<?='):
            in_php = True
            is_echo = True
            continue
        elif part.startswith('<?'):
            in_php = True
            is_echo = False
            continue
        elif part == '?>':
            in_php = False
            is_echo = False
            continue

        if not in_php:
            sys.stdout.write(part)
        else:
            if is_echo:
                val = eval_php_expr(part, env, filename)
                sys.stdout.write(str(val))
                is_echo = False
            else:
                exec_php_statements(part, env, filename)

def eval_php_expr(expr, env, filename="Command line code"):
    expr = expr.strip()
    if not expr:
        return ""
    if expr == '$argv':
        return env.get('argv')
    elif expr == '$argc':
        return env.get('argc')
    elif expr == '$argn':
        return env.get('argn', '')
    elif expr == '$argi':
        return env.get('argi', 0)
    elif expr.startswith('$'):
        var_name = expr[1:]
        if var_name in env:
            return env[var_name]
        sys.stdout.write(f"\nWarning: Undefined variable ${var_name} in {filename} on line 1\n")
        return None
    elif expr.startswith('"') and expr.endswith('"'):
        val = expr[1:-1].encode().decode('unicode_escape')
        def repl(m):
            vname = m.group(1) or m.group(2)
            return str(env.get(vname, ''))
        val = re.sub(r'\{\$([a-zA-Z_]\w*)\}|\$([a-zA-Z_]\w*)', repl, val)
        return val
    elif expr.startswith("'") and expr.endswith("'"):
        return expr[1:-1]
    try:
        return int(expr)
    except ValueError:
        try:
            return float(expr)
        except ValueError:
            return expr

def exec_php_statements(stmt_str, env, filename):
    stmts = stmt_str.split(';')
    for stmt in stmts:
        stmt = stmt.strip()
        if not stmt:
            continue
        stmt = re.sub(r'//.*$', '', stmt)
        stmt = re.sub(r'#.*$', '', stmt)
        stmt = re.sub(r'/\*[\s\S]*?\*/', '', stmt)
        stmt = stmt.strip()
        if not stmt:
            continue

        if stmt.startswith('echo ') or stmt.startswith('echo('):
            expr = stmt[4:].strip().rstrip(';')
            if expr.startswith('(') and expr.endswith(')'):
                expr = expr[1:-1].strip()
            parts = expr.split('.')
            for p in parts:
                p = p.strip()
                if p == '$argv' or p == 'var_dump($argv)':
                    sys.stdout.write(php_var_dump(env.get('argv')))
                elif p == '$argc':
                    sys.stdout.write(str(env.get('argc')))
                elif p == '$argn':
                    sys.stdout.write(str(env.get('argn', '')))
                elif p == '$argi':
                    sys.stdout.write(str(env.get('argi', 0)))
                elif p.startswith('$'):
                    vname = p[1:]
                    if vname in env:
                        sys.stdout.write(str(env[vname]))
                    else:
                        sys.stdout.write(f"\nWarning: Undefined variable ${vname} in {filename} on line 1\n")
                elif p.startswith('"') and p.endswith('"'):
                    val = p[1:-1].encode().decode('unicode_escape')
                    def repl(m):
                        vname = m.group(1) or m.group(2)
                        return str(env.get(vname, ''))
                    val = re.sub(r'\{\$([a-zA-Z_]\w*)\}|\$([a-zA-Z_]\w*)', repl, val)
                    sys.stdout.write(val)
                elif p.startswith("'") and p.endswith("'"):
                    sys.stdout.write(p[1:-1])
                else:
                    sys.stdout.write(p)
        elif stmt.startswith('var_dump('):
            expr = stmt[9:].rstrip(')').strip()
            if expr == '$argv':
                sys.stdout.write(php_var_dump(env.get('argv')))
            elif expr.startswith('$'):
                vname = expr[1:]
                if vname in env:
                    sys.stdout.write(php_var_dump(env[vname]))
                else:
                    sys.stdout.write(f"\nWarning: Undefined variable ${vname} in {filename} on line 1\n")
                    sys.stdout.write(php_var_dump(None))
            else:
                sys.stdout.write(php_var_dump(eval_php_expr(expr, env, filename)))
        elif '=' in stmt and not any(op in stmt for op in ['==', '!=', '<=', '>=']):
            var_part, val_part = stmt.split('=', 1)
            var_name = var_part.strip().replace('$', '')
            val = eval_php_expr(val_part, env, filename)
            env[var_name] = val

if __name__ == '__main__':
    main()
